#!/usr/bin/env bash
#
# Ключ зеркала conan-бинарников.
#
# Печатает короткий хеш, однозначно определяющий содержимое зависимостей. Имя
# ассета в релизе `deps-cache` строится из него, поэтому считать ключ обязаны
# одинаково и тот workflow, что зеркало наполняет, и те, что из него берут.
# Отсюда отдельный файл: разъехавшиеся копии дали бы вечный промах мимо кеша,
# причём молча - сборка осталась бы зелёной, просто медленной.
#
# Берём хеши деревьев из git, а не считаем файлы сами: git уже посчитал их при
# коммите, и tree-хеш меняется от любой правки внутри каталога.
#
# Использование:
#   .github/deps-key.sh <версия conan>

set -euo pipefail

conan_version="${1:?первым аргументом нужна версия conan}"

# Всё, что влияет на состав и сборку зависимостей. Список повторяет тот, по
# которому апстрим решал, пересобирать ли prebuilts.
paths=(
    recipes
    conanfile.py
    cmake/conan_provider.cmake
    cmake/platform_settings.cmake
    cmake/recipes_bootstrap.cmake
)

{
    for path in "${paths[@]}"; do
        git rev-parse "HEAD:${path}"
    done
    echo "conan-${conan_version}"
} | sha256sum | cut -c1-16
